```python
from collections import deque

def level_order(root):
    if not root:
        return []
    result, queue = [], deque([root])
    while queue:
        level_size = len(queue)  # snapshot BEFORE the inner loop starts
        level = []
        for _ in range(level_size):
            node = queue.popleft()
            level.append(node.val)
            if node.left: queue.append(node.left)
            if node.right: queue.append(node.right)
        result.append(level)
    return result
```

The `level_size = len(queue)` snapshot, taken before the inner loop runs, is what separates "all nodes" from "nodes grouped by level" — see the pitfall slide for what breaks without it.

```python
def zigzag_level_order(root):
    if not root:
        return []
    result, queue, left_to_right = [], deque([root]), True
    while queue:
        level_size = len(queue)
        level = deque()
        for _ in range(level_size):
            node = queue.popleft()
            if left_to_right:
                level.append(node.val)
            else:
                level.appendleft(node.val)  # insert at front to reverse for free
            if node.left: queue.append(node.left)
            if node.right: queue.append(node.right)
        result.append(list(level))
        left_to_right = not left_to_right
    return result
```

Using a deque for the level's output and appending at whichever end matches the current direction avoids a separate reversal pass — a small efficiency win, though a plain list plus `level.reverse()` before appending is equally correct and arguably easier to read.
